"""OMOP clinical query methods with privately configured source identifiers.

Dataset/table identifiers must be supplied inside an authorized environment.
Concept IDs and OMOP schema fields describe methods, not participant results.
This module performs no BigQuery writes and no data access at import time.
"""
import re
import string

QUERIES = {'person_q': 'SELECT p.person_id, p.birth_datetime\n    FROM `{source_dataset}.person` p\n    JOIN `{cohort_table}` c\n      ON p.person_id = c.person_id', 'bc_dx_q': 'WITH bc_dx AS (\n      SELECT co.person_id, DATE(co.condition_start_datetime) AS dx_date\n      FROM `{source_dataset}.condition_occurrence` co\n      JOIN `{cohort_table}` u ON co.person_id = u.person_id\n      JOIN `{source_dataset}.concept_ancestor` ca ON co.condition_concept_id = ca.descendant_concept_id\n      WHERE ca.ancestor_concept_id = 4112853\n    )\n    SELECT\n      person_id,\n      MIN(dx_date) AS first_bc_dx_date,\n      COUNT(DISTINCT dx_date) AS n_distinct_bc_dx_dates\n    FROM bc_dx\n    GROUP BY person_id', 'any_cancer_q': 'SELECT DISTINCT co.person_id\n    FROM `{source_dataset}.condition_occurrence` co\n    JOIN `{cohort_table}` u ON co.person_id = u.person_id\n    JOIN `{source_dataset}.concept_ancestor` ca ON co.condition_concept_id = ca.descendant_concept_id\n    WHERE ca.ancestor_concept_id = 443392', 'ehr_dates_q': 'WITH domain_dates AS (\n      SELECT co.person_id, co.condition_start_date AS event_date\n      FROM `{source_dataset}.condition_occurrence` co\n      JOIN `{cohort_table}` u ON co.person_id = u.person_id\n      UNION ALL\n      SELECT po.person_id, po.procedure_date AS event_date\n      FROM `{source_dataset}.procedure_occurrence` po\n      JOIN `{cohort_table}` u ON po.person_id = u.person_id\n      UNION ALL\n      SELECT de.person_id, de.drug_exposure_start_date AS event_date\n      FROM `{source_dataset}.drug_exposure` de\n      JOIN `{cohort_table}` u ON de.person_id = u.person_id\n      UNION ALL\n      SELECT m.person_id, m.measurement_date AS event_date\n      FROM `{source_dataset}.measurement` m\n      JOIN `{cohort_table}` u ON m.person_id = u.person_id\n      UNION ALL\n      SELECT vo.person_id, vo.visit_start_date AS event_date\n      FROM `{source_dataset}.visit_occurrence` vo\n      JOIN `{cohort_table}` u ON vo.person_id = u.person_id\n    )\n    SELECT\n      person_id,\n      MIN(event_date) AS ehr_first_date,\n      MAX(event_date) AS ehr_last_date,\n      COUNT(DISTINCT event_date) AS n_distinct_ehr_dates\n    FROM domain_dates\n    GROUP BY person_id', 'dx_count_q': 'SELECT co.person_id, COUNT(*) AS dx_code_occurrence_count\n    FROM `{source_dataset}.condition_occurrence` co\n    JOIN `{cohort_table}` u ON co.person_id = u.person_id\n    GROUP BY co.person_id', 'consent_q': 'SELECT u.person_id, csp.age_at_consent\n    FROM `{cohort_table}` u\n    JOIN `{source_dataset}.cb_search_person` csp ON u.person_id = csp.person_id', 'death_q': 'SELECT\n      u.person_id,\n      MIN(COALESCE(ad.death_date, d.death_date)) AS death_date\n    FROM `{cohort_table}` u\n    LEFT JOIN `{source_dataset}.death` d ON u.person_id = d.person_id\n    LEFT JOIN (\n      SELECT person_id, death_date\n      FROM `{source_dataset}.aou_death`\n      WHERE primary_death_record = TRUE\n    ) ad ON u.person_id = ad.person_id\n    WHERE d.death_date IS NOT NULL OR ad.death_date IS NOT NULL\n    GROUP BY u.person_id', 'bmi_query': 'SELECT person_id, bmi_value, measurement_date\n    FROM (\n      SELECT cc.person_id, m.value_as_number AS bmi_value, m.measurement_date,\n             ROW_NUMBER() OVER (PARTITION BY cc.person_id ORDER BY m.measurement_date DESC) AS rn\n      FROM `{cohort_table}` cc\n      JOIN `{source_dataset}.measurement` m ON cc.person_id = m.person_id\n      WHERE m.measurement_concept_id = 3038553\n        AND m.value_as_number IS NOT NULL\n        AND m.value_as_number BETWEEN 10 AND 100\n    )\n    WHERE rn = 1', 'menopause_query': 'SELECT person_id, answer\n    FROM (\n      SELECT cc.person_id, s.answer, s.survey_datetime,\n             ROW_NUMBER() OVER (PARTITION BY cc.person_id ORDER BY s.survey_datetime DESC) AS rn\n      FROM `{cohort_table}` cc\n      JOIN `{source_dataset}.ds_survey` s ON cc.person_id = s.person_id\n      WHERE s.question_concept_id = 1585784\n    )\n    WHERE rn = 1', 'pregnancy_query': 'SELECT person_id, answer\n    FROM (\n      SELECT cc.person_id, s.answer, s.survey_datetime,\n             ROW_NUMBER() OVER (PARTITION BY cc.person_id ORDER BY s.survey_datetime DESC) AS rn\n      FROM `{cohort_table}` cc\n      JOIN `{source_dataset}.ds_survey` s ON cc.person_id = s.person_id\n      WHERE s.question_concept_id = 1585811\n    )\n    WHERE rn = 1', 'famhist_query': 'SELECT cc.person_id, s.answer\n    FROM `{cohort_table}` cc\n    JOIN `{source_dataset}.ds_survey` s ON cc.person_id = s.person_id\n    WHERE s.question_concept_id = 836772', 'smk1_query': 'SELECT person_id, answer AS ans_100cigs\n    FROM (\n      SELECT cc.person_id, s.answer, s.survey_datetime,\n             ROW_NUMBER() OVER (PARTITION BY cc.person_id ORDER BY s.survey_datetime DESC) AS rn\n      FROM `{cohort_table}` cc\n      JOIN `{source_dataset}.ds_survey` s ON cc.person_id = s.person_id\n      WHERE s.question_concept_id = 1585857\n    )\n    WHERE rn = 1', 'smk2_query': 'SELECT person_id, answer AS ans_freq\n    FROM (\n      SELECT cc.person_id, s.answer, s.survey_datetime,\n             ROW_NUMBER() OVER (PARTITION BY cc.person_id ORDER BY s.survey_datetime DESC) AS rn\n      FROM `{cohort_table}` cc\n      JOIN `{source_dataset}.ds_survey` s ON cc.person_id = s.person_id\n      WHERE s.question_concept_id = 1585860\n    )\n    WHERE rn = 1', 'female_cohort': 'WITH breast_cancer_patients AS (\n SELECT DISTINCT co.person_id FROM `{source_dataset}.condition_occurrence` co\n JOIN `{source_dataset}.concept_ancestor` ca ON co.condition_concept_id = ca.descendant_concept_id\n WHERE ca.ancestor_concept_id = 4112853\n)\nSELECT p.person_id, p.race_concept_id,\n CASE WHEN bc.person_id IS NOT NULL THEN 1 ELSE 0 END AS is_case\nFROM `{source_dataset}.person` p\nLEFT JOIN breast_cancer_patients bc ON p.person_id = bc.person_id\nWHERE p.sex_at_birth_concept_id = 45878463'}


def render_query(name, identifiers):
    template = QUERIES[name]
    required = {field for _, field, _, _ in string.Formatter().parse(template) if field}
    for field in required:
        value = str(identifiers[field])
        if not re.fullmatch(r'[A-Za-z0-9_.-]+', value):
            raise ValueError('Invalid privately configured SQL identifier')
    return template.format(**identifiers)
